'use client';

import { useEffect, useRef, useState } from 'react';
import type { ProctorShieldClient } from '../../core/ProctorShieldClient';
import { ProctorChatClient } from '../../events/ProctorChatClient';

export interface ProctorLiveViewProps {
  client: ProctorShieldClient;
  /** Tenant admin JWT (used to authenticate WS as a proctor) */
  bearerToken: string;
  sessionId: string;
  /** Base API URL (used to build wss:// URL); defaults to client.options.baseUrl */
  baseUrl?: string;
  brandPrimary?: string;
  /** Optional: latest known snapshot URL or thumbnail */
  snapshotUrl?: string;
}

interface FaceCheckRow {
  occurred_at: string;
  face_count: number;
  violations: string[];
  detector: string;
}

/**
 * Live proctor side panel: chat with the candidate, see their latest face-check
 * results, last snapshot, and trigger pause / extend / terminate from one place.
 */
export function ProctorLiveView(props: ProctorLiveViewProps) {
  const { client, bearerToken, sessionId, brandPrimary = '#0f172a' } = props;
  const baseUrl = props.baseUrl || (client as unknown as { options: { baseUrl: string } }).options.baseUrl;

  const [messages, setMessages] = useState<Array<{ sender_type: string; message: string; created_at: string }>>([]);
  const [draft, setDraft] = useState('');
  const [face, setFace] = useState<FaceCheckRow[]>([]);
  const [status, setStatus] = useState<{ status?: string; paused_at?: string; scheduled_end?: string }>({});
  const [extraSeconds, setExtraSeconds] = useState(300);
  const [annot, setAnnot] = useState('');
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const chatRef = useRef<ProctorChatClient | null>(null);

  const refresh = async () => {
    try {
      const [chat, faces] = await Promise.all([
        client.listSessionChat(sessionId, 100),
        client.listSessionFaceChecks(sessionId, 30),
      ]);
      setMessages((chat.data as typeof messages) || []);
      setFace((faces.data as FaceCheckRow[]) || []);
    } catch (e) {
      setErr((e as Error).message);
    }
  };

  useEffect(() => {
    void refresh();
    const wsUrl = `${baseUrl.replace(/^http:/, 'ws:').replace(/^https:/, 'wss:')}/v1/sdk/ws/sessions/${sessionId}`;
    chatRef.current = new ProctorChatClient({ wsUrl, token: bearerToken, asProctor: true });
    chatRef.current.connect();
    chatRef.current.on((msg) => {
      const t = (msg as { type?: string }).type;
      if (t === 'chat_message') {
        setMessages((prev) => [
          ...prev,
          msg as unknown as { sender_type: string; message: string; created_at: string },
        ]);
      }
      if (t === 'status') {
        setStatus(msg as typeof status);
      }
    });
    chatRef.current.pollStatus();
    const poll = setInterval(() => chatRef.current?.pollStatus(), 10_000);
    return () => {
      clearInterval(poll);
      chatRef.current?.close();
    };
  }, [sessionId, bearerToken, baseUrl]);

  const send = async () => {
    const m = draft.trim();
    if (!m) return;
    setDraft('');
    const sent = chatRef.current?.sendChat(m);
    if (!sent) {
      try {
        await client.postSessionChat(sessionId, m);
      } catch (e) {
        setErr((e as Error).message);
      }
    }
  };

  const wrap = async (fn: () => Promise<unknown>) => {
    setBusy(true);
    setErr(null);
    try {
      await fn();
      await refresh();
    } catch (e) {
      setErr((e as Error).message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: 16 }}>
      <section style={{ background: '#fff', border: '1px solid #e2e8f0', borderRadius: 12, padding: 16 }}>
        <h2 style={{ marginTop: 0, color: brandPrimary }}>Live proctor</h2>
        <p style={{ color: '#475569', fontSize: 13 }}>
          Session <code>{sessionId.slice(0, 8)}…</code> · status{' '}
          <strong>{status.status || 'unknown'}</strong>
          {status.paused_at ? ' (paused)' : ''}
        </p>
        {props.snapshotUrl && (
          <img src={props.snapshotUrl} alt="Latest" style={{ width: '100%', borderRadius: 8, marginBottom: 12 }} />
        )}
        <h3 style={{ fontSize: 14, marginBottom: 6 }}>Recent face checks (every 10s)</h3>
        <div style={{ maxHeight: 200, overflowY: 'auto', fontSize: 12, fontFamily: 'monospace' }}>
          {face.length === 0 ? (
            <p style={{ color: '#94a3b8' }}>No checks yet.</p>
          ) : (
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead>
                <tr>
                  <th style={{ textAlign: 'left', borderBottom: '1px solid #e2e8f0' }}>Time</th>
                  <th style={{ textAlign: 'left', borderBottom: '1px solid #e2e8f0' }}>Faces</th>
                  <th style={{ textAlign: 'left', borderBottom: '1px solid #e2e8f0' }}>Violations</th>
                </tr>
              </thead>
              <tbody>
                {face
                  .slice()
                  .reverse()
                  .map((f, i) => (
                    <tr key={i}>
                      <td>{new Date(f.occurred_at).toLocaleTimeString()}</td>
                      <td style={{ color: f.face_count === 1 ? '#16a34a' : '#b91c1c' }}>{f.face_count}</td>
                      <td>{f.violations?.join(', ') || '—'}</td>
                    </tr>
                  ))}
              </tbody>
            </table>
          )}
        </div>
      </section>

      <section style={{ background: '#fff', border: '1px solid #e2e8f0', borderRadius: 12, padding: 16, display: 'flex', flexDirection: 'column' }}>
        <h3 style={{ marginTop: 0, color: brandPrimary }}>Controls</h3>
        {err && <p style={{ color: '#b91c1c', fontSize: 12 }}>{err}</p>}
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 12 }}>
          <button
            type="button"
            disabled={busy}
            onClick={() => void wrap(() => client.pauseSession(sessionId))}
            style={{ background: '#d97706', color: '#fff', border: 'none', borderRadius: 6, padding: '6px 10px', cursor: 'pointer' }}
          >
            Pause
          </button>
          <button
            type="button"
            disabled={busy}
            onClick={() => void wrap(() => client.resumeSession(sessionId))}
            style={{ background: '#16a34a', color: '#fff', border: 'none', borderRadius: 6, padding: '6px 10px', cursor: 'pointer' }}
          >
            Resume
          </button>
          <button
            type="button"
            disabled={busy}
            onClick={() => void wrap(() => client.terminateSession(sessionId))}
            style={{ background: '#b91c1c', color: '#fff', border: 'none', borderRadius: 6, padding: '6px 10px', cursor: 'pointer' }}
          >
            Terminate
          </button>
        </div>
        <div style={{ marginBottom: 12 }}>
          <label style={{ display: 'block', fontSize: 12, color: '#475569' }}>Extend time (seconds)</label>
          <div style={{ display: 'flex', gap: 6 }}>
            <input
              type="number"
              min={30}
              value={extraSeconds}
              onChange={(e) => setExtraSeconds(parseInt(e.target.value, 10) || 0)}
              style={{ flex: 1, padding: '4px 6px', border: '1px solid #cbd5e1', borderRadius: 6 }}
            />
            <button
              type="button"
              disabled={busy || !extraSeconds}
              onClick={() => void wrap(() => client.extendSession(sessionId, extraSeconds))}
              style={{ background: brandPrimary, color: '#fff', border: 'none', borderRadius: 6, padding: '4px 10px', cursor: 'pointer' }}
            >
              Extend
            </button>
          </div>
        </div>
        <div style={{ marginBottom: 12 }}>
          <label style={{ display: 'block', fontSize: 12, color: '#475569' }}>Proctor note</label>
          <textarea
            value={annot}
            onChange={(e) => setAnnot(e.target.value)}
            rows={2}
            style={{ width: '100%', border: '1px solid #cbd5e1', borderRadius: 6, padding: 6 }}
          />
          <button
            type="button"
            disabled={busy || !annot.trim()}
            onClick={() =>
              void wrap(async () => {
                await client.annotateSession(sessionId, annot.trim());
                setAnnot('');
              })
            }
            style={{ marginTop: 4, background: brandPrimary, color: '#fff', border: 'none', borderRadius: 6, padding: '4px 10px', cursor: 'pointer' }}
          >
            Save note
          </button>
        </div>

        <h3 style={{ marginTop: 0, marginBottom: 6, color: brandPrimary, fontSize: 14 }}>Chat</h3>
        <div style={{ flex: 1, overflowY: 'auto', border: '1px solid #e2e8f0', borderRadius: 6, padding: 8, fontSize: 13, minHeight: 200 }}>
          {messages.length === 0 ? (
            <p style={{ color: '#94a3b8', margin: 0 }}>No messages yet.</p>
          ) : (
            messages.map((m, i) => (
              <div key={i} style={{ marginBottom: 6 }}>
                <div style={{ color: '#64748b', fontSize: 11 }}>
                  {m.sender_type} · {new Date(m.created_at).toLocaleTimeString()}
                </div>
                <div>{m.message}</div>
              </div>
            ))
          )}
        </div>
        <form
          onSubmit={(e) => {
            e.preventDefault();
            void send();
          }}
          style={{ display: 'flex', marginTop: 6 }}
        >
          <input
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Message candidate…"
            style={{ flex: 1, padding: '6px 8px', border: '1px solid #cbd5e1', borderRadius: 6, fontSize: 13 }}
          />
          <button
            type="submit"
            style={{ marginLeft: 6, background: brandPrimary, color: '#fff', border: 'none', borderRadius: 6, padding: '6px 12px', cursor: 'pointer' }}
          >
            Send
          </button>
        </form>
      </section>
    </div>
  );
}
